/* nmhe_oneGround:(x0[656],p[473],lbx[656],ubx[656],lbg[640],ubg[640],lam_x0[656],lam_g0[640])->(x[656],f,g[640],lam_x[656],lam_g[640],lam_p[473]) */
static int casadi_f0(const casadi_real** arg, casadi_real** res, casadi_int* iw, casadi_real* w, int mem) {
  const casadi_real one=1;
  static struct casadi_ocp_block block_AB[40], block_CD[41], block_I[40], block_RSQ[41];
  struct casadi_fatrop_data* d=&casadi_f0_mem[mem];
  struct casadi_fatrop_prob p;
  struct casadi_nlpsol_data d_nlp;
  struct casadi_nlpsol_prob p_nlp;
  struct casadi_oracle_data d_oracle;
  d_nlp.oracle = &d_oracle;
  d_nlp.p = arg[1];
  d_nlp.lbx = arg[2];
  d_nlp.ubx = arg[3];
  d_nlp.lbg = arg[4];
  d_nlp.ubg = arg[5];
  d_nlp.x0 = arg[0];
  d_nlp.lam_x0 = arg[6];
  d_nlp.lam_g0 = arg[7];
  d_nlp.x = res[0];
  d_nlp.f = res[1];
  d_nlp.g = res[2];
  d_nlp.lam_x = res[3];
  d_nlp.lam_g = res[4];
  d_nlp.lam_p = res[5];
  d_nlp.prob = &p_nlp;
  p_nlp.nx = 656;
  p_nlp.ng = 640;
  p_nlp.np = 473;
  p_nlp.detect_bounds.ng = 0;
  casadi_nlpsol_init(&d_nlp, &arg, &res, &iw, &w);
  if (d_nlp.x0) {
    casadi_copy(d_nlp.x0, 656, d_nlp.z);
  } else {
    casadi_clear(d_nlp.z, 656);
  }
  if (d_nlp.lbx) {
    casadi_copy(d_nlp.lbx, 656, d_nlp.lbz);
  } else {
    casadi_fill(d_nlp.lbz, 656, -casadi_inf);
  }
  if (d_nlp.ubx) {
    casadi_copy(d_nlp.ubx, 656, d_nlp.ubz);
  } else {
    casadi_fill(d_nlp.ubz, 656, casadi_inf);
  }
  if (d_nlp.lam_x0) {
    casadi_copy(d_nlp.lam_x0, 656, d_nlp.lam);
  } else {
    casadi_clear(d_nlp.lam, 656);
  }
  if (d_nlp.lbg) {
    casadi_copy(d_nlp.lbg, 640, d_nlp.lbz+656);
  } else {
    casadi_fill(d_nlp.lbz+656, 640, -casadi_inf);
  }
  if (d_nlp.ubg) {
    casadi_copy(d_nlp.ubg, 640, d_nlp.ubz+656);
  } else {
    casadi_fill(d_nlp.ubz+656, 640, casadi_inf);
  }
  if (d_nlp.lam_g0) {
    casadi_copy(d_nlp.lam_g0, 640, d_nlp.lam+656);
  } else {
    casadi_clear(d_nlp.lam+656, 640);
  }
  d->nlp = &d_nlp;
  d->prob = &p;
  p.nlp = &p_nlp;
  p.nx = casadi_s0;
  p.nu = casadi_s1;
  p.ABsp = casadi_s2;
  p.AB_offsets = casadi_s3;
  p.CDsp = casadi_s4;
  p.CD_offsets = casadi_s5;
  p.RSQsp = casadi_s6;
  p.RSQ_offsets = casadi_s7;
  p.Isp = casadi_s8;
  p.I_offsets = casadi_s9;
  p.AB = block_AB;
  casadi_unpack_ocp_blocks(p.AB, casadi_s10);
  p.CD = block_CD;
  casadi_unpack_ocp_blocks(p.CD, casadi_s11);
  p.RSQ = block_RSQ;
  casadi_unpack_ocp_blocks(p.RSQ, casadi_s12);
  p.I = block_I;
  casadi_unpack_ocp_blocks(p.I, casadi_s13);
  p.N = 40;
  p.nlp_jac_g.checkout = 0;
  p.nlp_jac_g.eval = casadi_f5;
  p.nlp_jac_g.release = 0;
  p.nlp_grad_f.checkout = 0;
  p.nlp_grad_f.eval = casadi_f3;
  p.nlp_grad_f.release = 0;
  p.nlp_f.checkout = 0;
  p.nlp_f.eval = casadi_f2;
  p.nlp_f.release = 0;
  p.nlp_g.checkout = 0;
  p.nlp_g.eval = casadi_f4;
  p.nlp_g.release = 0;
  p.nlp_hess_l.checkout = 0;
  p.nlp_hess_l.eval = casadi_f6;
  p.nlp_hess_l.release = 0;
  p.sp_a = casadi_s14;
  p.sp_h = casadi_s15;
  p.write = &casadi_fatrop_cb_write;
  p.flush = &casadi_fatrop_cb_flush;
  casadi_fatrop_setup(&p);
  casadi_fatrop_init(d, &arg, &res, &iw, &w);
  casadi_oracle_init(d->nlp->oracle, &arg, &res, &iw, &w);
  casadi_fatrop_presolve(d);
  fatrop_ocp_c_set_option_double(d->solver, "acceptable_tol", 0.0001);
  fatrop_ocp_c_set_option_int(d->solver, "max_iter", 20);
  fatrop_ocp_c_set_option_double(d->solver, "mu_init", 0.001);
  fatrop_ocp_c_set_option_int(d->solver, "print_level", 0);
  fatrop_ocp_c_set_option_double(d->solver, "tol", 1e-05);
  casadi_fatrop_solve(d);
  d->arg[0] = d_nlp.z;
  d->arg[1] = d_nlp.p;
  d->arg[2] = &one;
  d->arg[3] = d_nlp.lam+656;
  d->res[0] = &d_nlp.objective;
  d->res[1] = d_nlp.z+656;
  d->res[2] = 0;
  d->res[3] = d_nlp.lam_p;
  if (casadi_f1(d->arg, d->res, d->iw, d->w, 0)) return 1;
  casadi_scal(473, -1.0, d_nlp.lam_p);
  casadi_copy(d_nlp.z, 656, d_nlp.x);
  casadi_copy(d_nlp.z + 656, 640, d_nlp.g);
  casadi_copy(d_nlp.lam, 656, d_nlp.lam_x);
  casadi_copy(d_nlp.lam + 656, 640, d_nlp.lam_g);
  if (d_nlp.f) casadi_copy(&d_nlp.objective, 1, d_nlp.f);
  if (d_nlp.lam_p) casadi_copy(d_nlp.lam_p, 473, d_nlp.lam_p);
  return 0;
  return 0;
}

int casadi_f0_alloc_mem(void) {
  return casadi_f0_mem_counter++;
}

int casadi_f0_init_mem(int mem) {
  fatrop_init_mem(&casadi_f0_mem[mem]);
  return 0;
}

void casadi_f0_free_mem(int mem) {
  fatrop_free_mem(&casadi_f0_mem[mem]);
}

int casadi_f0_checkout(void) {
  int mid;
  if (casadi_f0_unused_stack_counter>=0) {
    return casadi_f0_unused_stack[casadi_f0_unused_stack_counter--];
  } else {
    if (casadi_f0_mem_counter==CASADI_MAX_NUM_THREADS) return -1;
    mid = casadi_f0_alloc_mem();
    if (mid<0) return -1;
    if(casadi_f0_init_mem(mid)) return -1;
    return mid;
  }
}

void casadi_f0_release(int mem) {
  casadi_f0_unused_stack[++casadi_f0_unused_stack_counter] = mem;
}

